struct Node;

/// Truncate `s` to at most `max` Unicode scalar values (chars), respecting
/// char boundaries so the result is always valid UTF-8 and `chars().count()
/// <= max`.
fn truncate_chars(s: &str, max: usize) -> String {
    match s.char_indices().nth(max) {
        Some((idx, _)) => s[..idx].to_string(),
        None => s.to_string(),
    }
}

impl Guest for Node {
    fn run(classified: ClassifiedItem) -> ItemVerdict {
        let item = &classified.item;

        // Extended grant: fetch an enrichment record for this input from the
        // metadata service. `fetch` returns transport failures as values, so a
        // service that is down does not change the node's output.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            item.text
        );
        let enrichment = match crate::aap::caps::http_client::fetch(&url) {
            Ok(body) => body,
            Err(_) => String::new(),
        };

        let system = "You summarise a single classified feed item in at most \
                      400 characters. Return only the summary text.";
        let prompt = format!(
            "Title: {title}\nFeed: {feed}\nLink: {link}\nPublished: {published}\n\
             Enrichment: {enrichment}\n\nText:\n{text}",
            title = item.title,
            feed = item.feed,
            link = item.link,
            published = item.published,
            enrichment = enrichment,
            text = item.text,
        );

        let raw = crate::aap::caps::inference_llm::infer(system, &prompt, "summarise");

        // ensures len(summary) <= 400
        let summary = truncate_chars(raw.trim(), 400);

        ItemVerdict {
            id: item.id.clone(),
            feed: item.feed.clone(),
            title: item.title.clone(),
            link: item.link.clone(),
            category: classified.category,
            importance: classified.importance,
            summary,
            // ensures kept == true
            kept: true,
        }
    }
}

export!(Node);
```

